    'game.bc3Desc':     { en: 'Lower-resolution but important collector image. It appears to match the commercial board layout closely.', zh: '\u5206\u8FA8\u7387\u8F83\u4F4E\uFF0C\u4F46\u662F\u91CD\u8981\u7684\u6536\u85CF\u8005\u56FE\u50CF\u3002\u5176\u5E03\u5C40\u4E0E\u5546\u4E1A\u7248\u68CB\u76D8\u9AD8\u5EA6\u63A5\u8FD1\u3002' },
