    'game.bc4Desc':     { en: 'Board shown with play pieces and card piles in place. Useful for comparing actual play presentation.', zh: '\u68CB\u76D8\u4E0A\u653E\u6709\u68CB\u5B50\u548C\u5361\u5806\uFF0C\u53EF\u7528\u4E8E\u6BD4\u8F83\u5B9E\u9645\u6E38\u73A9\u65F6\u7684\u5448\u73B0\u65B9\u5F0F\u3002' },
