    'game.bc5Desc':     { en: 'World of Monopoly\'s back-board image shows the black underside and white label, a possible material clue for future object comparison.', zh: 'World of Monopoly \u7684\u68CB\u76D8\u80CC\u9762\u56FE\u663E\u793A\u9ED1\u8272\u5E95\u9762\u548C\u767D\u8272\u6807\u7B7E\uFF0C\u53EF\u80FD\u662F\u540E\u7EED\u5B9E\u7269\u6BD4\u8F83\u7684\u7269\u8D28\u7EBF\u7D22\u3002' },
