    're.boardTitle':    { en: 'The Board', zh: '棋盘' },
    're.boardLead':     { en: 'The Shanghai Real Estate board, from the Phil Orbanes collection, photographed by themonopolist.net.', zh: 'Shanghai Real Estate 棋盘，来自 Phil Orbanes 旧藏，themonopolist.net 拍摄。' },
    're.boardImgTitle': { en: 'Shanghai Real Estate board (full view)', zh: 'Shanghai Real Estate 棋盘（全貌）' },
    're.boardImgDesc':  { en: 'Phil Orbanes collection photograph. The board follows the Parker Brothers layout exactly, with Shanghai streets replacing Atlantic City names and shipping lines replacing railroads.', zh: 'Phil Orbanes 旧藏照片。棋盘完全遵循 Parker Brothers 布局，上海街道替换大西洋城名，航运公司替换铁路。' },
    're.squaresTitle':  { en: 'All 40 Squares', zh: '完整40格' },
    're.squaresLead':   { en: 'Complete board reading from GO, following the direction of play. All 22 property names verified against board photographs and Veldhuis\'s catalogue. Prices match the 1935 Parker Brothers edition exactly.', zh: '从 GO 开始按行进方向的完整棋盘读数。全部22条地产名称经棋盘照片和 Veldhuis 目录互证。价格与1935年 Parker Brothers 版完全一致。' },
